CREATE OR REPLACE FUNCTION public.opc_data_turn(a uuid, rid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE t turns;s runtime_sessions;body text;tomb jsonb;
BEGIN
 PERFORM 1 FROM profiles WHERE id=a FOR SHARE;
